Path parseSvgPath(String d) {
  final path = ui.Path();
  final tokens = <String>[];
  final re = RegExp(r'([MmLlHhVvCcSsQqTtAaZz])|([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)');
  for (final m in re.allMatches(d)) {
    tokens.add(m.group(0)!);
  }
  var i = 0;
  var cmd = '';
  double cx = 0, cy = 0, ox = 0, oy = 0, xc = 0, yc = 0;

  double next() => double.parse(tokens[i++]);
  bool hasNum() => i < tokens.length && RegExp(r'^[-+]?\d').hasMatch(tokens[i]);

  while (i < tokens.length) {
    final t = tokens[i];
    if (RegExp(r'^[A-Za-z]$').hasMatch(t)) {
      cmd = t;
      i++;
    }
    switch (cmd) {
      case 'M':
        cx = next(); cy = next();
        path.moveTo(cx, cy); ox = cx; oy = cy;
        cmd = 'L';
        break;
      case 'm':
        cx += next(); cy += next();
        path.moveTo(cx, cy); ox = cx; oy = cy;
        cmd = 'l';
        break;
      case 'L':
        cx = next(); cy = next();
        path.lineTo(cx, cy);
        break;
      case 'l':
        cx += next(); cy += next();
        path.lineTo(cx, cy);
        break;
      case 'H':
        cx = next();
        path.lineTo(cx, cy);
        break;
      case 'h':
        cx += next();
        path.lineTo(cx, cy);
        break;
      case 'V':
        cy = next();
        path.lineTo(cx, cy);
        break;
      case 'v':
        cy += next();
        path.lineTo(cx, cy);
        break;
      case 'C':
        final x1 = next(), y1 = next(), x2 = next(), y2 = next();
        cx = next(); cy = next();
        path.cubicTo(x1, y1, x2, y2, cx, cy);
        xc = x2; yc = y2;
        break;
      case 'c':
        final x1 = cx + next(), y1 = cy + next();
        final x2 = cx + next(), y2 = cy + next();
        cx += next(); cy += next();
        path.cubicTo(x1, y1, x2, y2, cx, cy);
        xc = x2; yc = y2;
        break;
      case 'S':
        final x2 = next(), y2 = next();
        final x1 = 2 * cx - xc, y1 = 2 * cy - yc;
        cx = next(); cy = next();
        path.cubicTo(x1, y1, x2, y2, cx, cy);
        xc = x2; yc = y2;
        break;
      case 's':
        final x2 = cx + next(), y2 = cy + next();
        final x1 = 2 * cx - xc, y1 = 2 * cy - yc;
        cx += next(); cy += next();
        path.cubicTo(x1, y1, x2, y2, cx, cy);
        xc = x2; yc = y2;
        break;
      case 'Q':
        final x1 = next(), y1 = next();
        cx = next(); cy = next();
        path.quadraticBezierTo(x1, y1, cx, cy);
        xc = x1; yc = y1;
        break;
      case 'q':
        final x1 = cx + next(), y1 = cy + next();
        cx += next(); cy += next();
        path.quadraticBezierTo(x1, y1, cx, cy);
        xc = x1; yc = y1;
        break;
      case 'T':
        final x1 = 2 * cx - xc, y1 = 2 * cy - yc;
        cx = next(); cy = next();
        path.quadraticBezierTo(x1, y1, cx, cy);
        xc = x1; yc = y1;
        break;
      case 't':
        final x1 = 2 * cx - xc, y1 = 2 * cy - yc;
        cx += next(); cy += next();
        path.quadraticBezierTo(x1, y1, cx, cy);
        xc = x1; yc = y1;
        break;
      case 'Z':
      case 'z':
        path.close();
        cx = ox; cy = oy;
        break;
      case 'A':
      case 'a':
        // Approximate arcs as lines to keep parser small; assets rarely need A.
        next();
        next();
        next();
        next();
        next(); // rx, ry, angle, large-arc, sweep
        if (cmd == 'A') {
          cx = next();
          cy = next();
        } else {
          cx += next();
          cy += next();
        }
        path.lineTo(cx, cy);
        break;
      default:
        if (hasNum()) {
          // repeated command args already handled by keeping cmd
          break;
        }
        i++;
        break;
    }
  }
  return path;
}

void drawEyeSvgAsset(Canvas canvas, Rect dst, int assetId, {Color? tint}) {
  final ops = kEyeSvgOps[assetId];
  if (ops == null) {
    return;
  }
  final scale = dst.width / kEyeSvgSize;
  canvas.save();
  canvas.translate(dst.left, dst.top);
  canvas.scale(scale, scale);

  // Basketball: clip seam strokes to the center ball so lines don't poke out.
  Path? basketballClip;
  if (assetId == 41 && ops.length > 1) {
    basketballClip = parseSvgPath(ops[1].d);
  }

  for (var i = 0; i < ops.length; i++) {
    final op = ops[i];
    final path = parseSvgPath(op.d)
      ..fillType =
          op.evenOdd ? PathFillType.evenOdd : PathFillType.nonZero;
    final paint = Paint()..isAntiAlias = true;
    if (op.gradientColors != null) {
      paint
        ..shader = ui.Gradient.linear(
          Offset(op.gradX1!, op.gradY1!),
          Offset(op.gradX2!, op.gradY2!),
          op.gradientColors!,
          op.gradientStops,
        )
        ..style = PaintingStyle.fill;
      canvas.drawPath(path, paint);
    } else if (op.fill != null) {
      paint
        ..style = PaintingStyle.fill
        ..color = tint ?? op.fill!;
      canvas.drawPath(path, paint);
    }
    if (op.stroke != null) {
      paint
        ..shader = null
        ..style = PaintingStyle.stroke
        ..strokeWidth = op.strokeWidth ?? 1.5
        ..color = tint ?? op.stroke!
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round;
      if (basketballClip != null && i > 1) {
        canvas.save();
        canvas.clipPath(basketballClip);
        canvas.drawPath(path, paint);
        canvas.restore();
      } else {
        canvas.drawPath(path, paint);
      }
    }
  }
  canvas.restore();
}

void drawDotSvgModule(
  Canvas canvas,
  Rect dst,
  int assetId,
  Paint paint, {
  int seed = 0,
}) {
  final asset = kDotModuleAssets[assetId];
  if (asset == null) {
    canvas.drawOval(dst, paint);
    return;
  }

  final useAccent = asset.accentD != null && seed.abs() % 8 == 0;
  final d = useAccent ? asset.accentD! : asset.d;
  final bx = useAccent ? asset.accentBx! : asset.bx;
  final by = useAccent ? asset.accentBy! : asset.by;
  final bw = useAccent ? asset.accentBw! : asset.bw;
  final bh = useAccent ? asset.accentBh! : asset.bh;

  final colored = Paint()
    ..isAntiAlias = true
    ..style = PaintingStyle.fill
    ..color = asset.palette[seed.abs() % asset.palette.length];
  // Honor caller color for mono palettes (themed QR color).
  if (asset.palette.length <= 1 && paint.color.a != 0) {
    colored.color = paint.color;
  }

  canvas.save();
  // Bars stretch to fill neighbor-merged rects; other dots keep
  // Figma aspect via uniform scale inside the pitch-padded cell.
  if (assetId == 16 || assetId == 17) {
    canvas.translate(dst.left, dst.top);
    canvas.scale(dst.width / bw, dst.height / bh);
    canvas.translate(-bx, -by);
  } else {
    final scale = dst.width / bw < dst.height / bh
        ? dst.width / bw
        : dst.height / bh;
    final dx = dst.left + (dst.width - bw * scale) / 2;
    final dy = dst.top + (dst.height - bh * scale) / 2;
    canvas.translate(dx, dy);
    canvas.scale(scale, scale);
    canvas.translate(-bx, -by);
  }
  canvas.drawPath(parseSvgPath(d), colored);
  canvas.restore();
}
